current.custom_css:
.m-product-card__title .m-product-card__name,
.m-richtext__subtitle,
.m-richtext__description {
  font-family: 'M-Body-Font';
}

.m-section__subheading,
.m-richtext__subtitle,
.m-product-card__price .m-price {
  font-weight: 700;
  color: #D22727;
}

.m-custom-promotion {
  border-top: 1px solid #eeeeee;
}

.m-custom-promotion .m-icon-box__content h3 {
  font-family: 'M-Body-Font';
  font-weight: 700;
  font-size: 18px;
}

.m-newsletter-form__wrapper {
  background: #fff;
}

.m-footer .m-footer--block:not(.m-footer--block-newsletter) .m-footer--block-title {
  font-family: 'M-Body-Font';
  font-weight: 700;
}

.m-menu .m-menu__item .m-menu__link--main {
  font-weight: 700;
  letter-spacing: 1px;
}

.m-product-card__title .m-product-card__name {
  font-weight: 700;
}

.m-footer .m-newsletter-form--bordered .m-newsletter-form__button {
  background-color: rgb(var(--color-button));
  border-color: rgb(var(--color-button));
  color: rgb(var(--color-button-text));
}
.m-footer .m-newsletter-form--bordered {
  --inputs-border-width: 0;
}

@media (min-width: 1280px) {
  .m-custom-content-block-text .m-custom-content__block-inner {
    padding-left: 60px;
  }

  .m-iwt--home .m-image-with-text__content {
    padding-left: 80px;
  }

  .m-footer .m-footer--block-newsletter .m-footer--block-title {
    font-size: 60px;
  }
}

@media (min-width: 1536px) {
  .m-custom-content-block-text .m-custom-content__block-inner {
    padding-left: 120px;
  }

  .m-iwt--home .m-image-with-text__content {
    padding-left: 200px;
  }

  .sf__custom-heading {
    font-size: 170px;
    line-height: 140px;
  }
}

@media (max-width: 767px) {
  .m-footer .m-footer--block-newsletter .m-footer--block-title {
    font-size: 1.5rem;
  }
}
